//! Test 14: the golden biquads.
//!
//! The coefficients in `biquad.rs` are checked against an *independent*
//! implementation of the same DSP: the author's own Python library, whose
//! `make_peak` factory follows the RBJ Audio EQ Cookbook. The golden file is
//! generated by `tools/gen_golden.py` and committed, so this test needs no
//! Python.
//!
//! This is the highest-value check in the suite: every other test asserts that
//! the engine does what we told it to do, and this one asserts that what we
//! told it to do is the right thing in the first place.

use sehrnoise_core::biquad::peaking_coeffs;

/// The golden file, relative to the crate root.
const GOLDEN_PATH: &str = "tests/data/golden_biquads.json";

/// How far a coefficient may differ from the reference, in absolute terms.
///
/// The reference is computed in double precision and our coefficients in single
/// precision, so they agree to about one part in a million.
const TOLERANCE: f32 = 1e-5;

#[test]
fn golden_biquads_match_the_reference_implementation() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(GOLDEN_PATH);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));

    let document: serde_json::Value =
        serde_json::from_str(&text).unwrap_or_else(|e| panic!("cannot parse the golden file: {e}"));

    let sample_rate = document["sample_rate"]
        .as_f64()
        .expect("the golden file has no sample rate") as f32;

    let cases = document["cases"]
        .as_array()
        .expect("the golden file has no cases");
    assert!(!cases.is_empty(), "the golden file holds no cases");

    for case in cases {
        let frequency = case["frequency_hz"].as_f64().expect("no frequency") as f32;
        let q = case["q"].as_f64().expect("no q") as f32;
        let gain_db = case["gain_db"].as_f64().expect("no gain") as f32;

        let ours = peaking_coeffs(frequency, q, gain_db, sample_rate);

        let compare = |name: &str, ours: f32, theirs: f64| {
            let theirs = theirs as f32;
            assert!(
                (ours - theirs).abs() <= TOLERANCE,
                "{name} at {frequency} Hz, Q {q}, {gain_db} dB: ours {ours:.9}, the reference {theirs:.9}"
            );
        };

        compare("b0", ours.b0, case["b0"].as_f64().expect("no b0"));
        compare("b1", ours.b1, case["b1"].as_f64().expect("no b1"));
        compare("b2", ours.b2, case["b2"].as_f64().expect("no b2"));
        compare("a1", ours.a1, case["a1"].as_f64().expect("no a1"));
        compare("a2", ours.a2, case["a2"].as_f64().expect("no a2"));
    }
}

#[test]
fn the_golden_file_covers_the_band_bank() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(GOLDEN_PATH);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    let document: serde_json::Value =
        serde_json::from_str(&text).expect("cannot parse the golden file");

    let cases = document["cases"].as_array().expect("no cases");

    // Every band centre of the bank is covered, at three gains.
    for frequency in [31, 73, 173, 411, 974, 2310, 5476, 12986] {
        let found = cases
            .iter()
            .filter(|case| case["frequency_hz"].as_f64() == Some(frequency as f64));
        assert!(
            found.count() >= 3,
            "the golden file does not cover {frequency} Hz at three gains"
        );
    }
}
